mapper.select:


    deleted_flag = 'N'
    and flowFormVersion.flow_code = #{flowCode}
    and flowFormVersion.flow_name like concat('%', #{flowName}, '%')
    and flowFormVersion.table_code = #{tableCode}
    and flowFormVersion.form_name like concat('%', #{formName}, '%')
    and flowFormVersion.publish_status = #{publishStatus}

order by flowFormVersion.flow_code asc, flowFormVersion.version desc
